import math, random, mmh3, time

def randbytes(n): return bytes([random.randint(0,255) for i in range(n)])

m = 2**32 - 5
k = 47

def fp(i):
    return pow(1 - math.pow(math.e, -k*i/m), k)

def security(i):
    v = 1/fp(i)
    return int(v).bit_length()

