    post_id = str(uuid.uuid4())
    cursor.execute(
        "INSERT INTO blog_posts (id, title, content, user_id) VALUES (?, ?, ?, ?)",
        (post_id, title, content, userid),
    )
    conn.commit()
    conn.close()
    return post_id


