SOLUTION_LEN = 64

def toPath(x: int):
	s = bin(x)[2:]
	if len(s) % 2 == 1:
		s = "0" + s

	path = ""
	for i in range(0, len(s), 2):
		path += directions[int(s[i:i+2], 2)]
	return path

def toInt(p: str):
	ret = 0
	for d in p:
		ret = ret * 4 + directions.index(d)
	return ret

