            Ok(_) => (),
            Err(_) => return,
        }
        let line = line.trim();

        if line.is_empty() {
            return;
        }

        let (nonce, encrypted) = cipher.encrypt(line.as_bytes());

        println!("ct: {} {}", hex::encode(nonce), hex::encode(encrypted));
    }
}

