import numpy as np

def gf2_mat_mul(A, B):
    return (A @ B) % 2

def gf2_mat_pow(M, e):
    n = M.shape[0]
    R = np.eye(n, dtype=int)
    base = M.copy()
    while e:
        if e & 1:
            R = gf2_mat_mul(R, base)
        base = gf2_mat_mul(base, base)
        e >>= 1
    return R

def xtime(x): return ((x<<1)&0xff) ^ (((x>>7)&1)*0x1b)
def apply_shift_rows(b):
    s = list(b)
    t=s[0*4+1]; s[0*4+1]=s[1*4+1]; s[1*4+1]=s[2*4+1]; s[2*4+1]=s[3*4+1]; s[3*4+1]=t
    t=s[0*4+2]; s[0*4+2]=s[2*4+2]; s[2*4+2]=t
    t=s[1*4+2]; s[1*4+2]=s[3*4+2]; s[3*4+2]=t
    t=s[0*4+3]; s[0*4+3]=s[3*4+3]; s[3*4+3]=s[2*4+3]; s[2*4+3]=s[1*4+3]; s[1*4+3]=t
    return s
def apply_mix_columns(b):
    s=list(b)
