        s[i*4+0] = a^b1^c^d ^ xtime(a^b1)
        s[i*4+1] = a^b1^c^d ^ xtime(b1^c)
        s[i*4+2] = a^b1^c^d ^ xtime(c^d)
        s[i*4+3] = a^b1^c^d ^ xtime(d^a)
    return s
