    g = 0
    for i in range(len(t)-2):
        g = gcd(g, t[i+2]*t[i] - t[i+1]*t[i+1])
    if g == 0:
        return None
    m = g
    # a from two consecutive differences
    a = (t[1] * mod_inverse(t[0] % m, m)) % m
    c = (xs[1] - a*xs[0]) % m
    # verify all
    for i in range(1, n):
        if (a*xs[i-1] + c) % m != xs[i]:
            return None
    return (m, a, c)

