# Local simulation of the challenge oracle
import random
from Crypto.Util.number import getPrime
directions = "LRUD"
SOLUTION_LEN = 64

def toPath(x):
    s = bin(x)[2:]
    if len(s) % 2 == 1:
        s = "0" + s
    path = ""
    for i in range(0, len(s), 2):
        path += directions[int(s[i:i+2], 2)]
    return path

def toInt(p):
    ret = 0
    for d in p:
        ret = ret*4 + directions.index(d)
    return ret

def final_position(path):
    return (path.count("R")-path.count("L"), path.count("U")-path.count("D"))

def displacement(x):
    return final_position(toPath(x))

class RSA:
    def __init__(self):
        self.p = getPrime(512)
        self.q = getPrime(512)
        self.n = self.p*self.q
        self.phi = (self.p-1)*(self.q-1)
        self.e = 65537
        self.d = pow(self.e, -1, self.phi)
    def encrypt(self, m): return pow(m, self.e, self.n)
    def decrypt(self, c): return pow(c, self.d, self.n)

def make_problem(seed=None):
    rng = random.Random(seed)
    solution = "".join(rng.choice(directions) for _ in range(SOLUTION_LEN))
    m = toInt(solution)
    rsa = RSA()
    C = rsa.encrypt(m)
    return rsa, m, solution, C

# oracle: given rsa and ciphertext C, query multiplier x -> displacement of m*x mod n
def oracle(rsa, C, x):
    c = C * pow(x, rsa.e, rsa.n) % rsa.n
    val = rsa.decrypt(c)
    return displacement(val), val

if __name__ == "__main__":
    rsa, m, sol, C = make_problem(1234)
    print("m bits:", m.bit_length())
    print("solution:", sol)
    for x in [1,2,3,4,5,7,15,63]:
        d, val = oracle(rsa, C, x)
        print(f"x={x}: disp={d}, val_lt_n_no_wrap={val==m*x}")
EOF
