import secrets

def getCRC16(msg, gen_poly):
    assert (1 << 16) <= gen_poly < (1 << 17)
    msglen = msg.bit_length()
    msg <<= 16
    for i in range(msglen - 1, -1, -1):
        if (msg >> (i + 16)) & 1:
            msg ^= (gen_poly << i)
    return msg

def rref(A, ncols):
    A = [row[:] for row in A]
    m = len(A)
    pivot_cols = []
    r = 0
    for c in range(ncols):
        piv = None
        for i in range(r, m):
            if A[i][c]:
                piv = i; break
        if piv is None: continue
        A[r], A[piv] = A[piv], A[r]
        for i in range(m):
            if i != r and A[i][c]:
                for j in range(c, ncols):
                    A[i][j] ^= A[r][j]
        pivot_cols.append(c)
        r += 1
    return A, r, pivot_cols

def nullspace_basis(M, ncols):
    A, rank, piv = rref([row[:] for row in M], ncols)
    pivset = set(piv)
    free = [c for c in range(ncols) if c not in pivset]
    basis = []
    for f in free:
        v = [0]*ncols
        v[f] = 1
        for row in A:
            pc=None
            for c in range(ncols):
                if row[c]:
                    pc=c;break
            if pc is not None and row[f]:
                v[pc] = 1
        basis.append(v)
    return basis

def build_M(polys, nkeys=512):
    M = []
    for gi in polys:
        for bit in range(16):
            row = [0]*nkeys
            for j in range(nkeys):
                msg = 1 << j
                crc = getCRC16(msg, gi)
                if (crc >> bit) & 1:
                    row[j] = 1
            M.append(row)
    return M

